extern "C" __global__ void k_cvt(float* out, long long* clk){
  float a[CH]; for(int i=0;i<CH;i++) a[i]=1.f+threadIdx.x*1e-6f+i*1e-3f;
  __syncthreads(); long long t0=clock64();
