  __syncthreads(); long long t0=clock64();
  #pragma unroll 2
  for(int it=0;it<IT;it++){
    #pragma unroll
    for(int i=0;i<CH;i++) asm volatile("ex2.approx.ftz.f32 %0,%0;":"+f"(a[i]));
    #pragma unroll
    for(int j=0;j<4;j++)
    #pragma unroll
    for(int i=0;i<CH/2;i++) asm volatile("fma.rn.f32x2 %0,%0,%1,%2;":"+l"(p[i]):"l"(b),"l"(c));
  }
  __syncthreads(); long long t1=clock64();
  float s=0; for(int i=0;i<CH;i++) s+=a[i]; for(int i=0;i<CH/2;i++){float x,y; asm("mov.b64 {%0,%1},%2;":"=f"(x),"=f"(y):"l"(p[i])); s+=x+y;}
  out[blockIdx.x*blockDim.x+threadIdx.x]=s;
  if(threadIdx.x==0) clk[blockIdx.x]=t1-t0;
}
'''
