src = r'''
#define CH 8
#define IT 4096
__device__ __forceinline__ long long gt(){ long long t; asm volatile("mov.u64 %0,%%globaltimer;":"=l"(t)); return t;}
extern "C" __global__ void k_ffma(float* out, long long* clk){
  float a[CH]; for(int i=0;i<CH;i++) a[i]=threadIdx.x*1e-3f+i;
  float b=1.0001f, c=1e-7f;
  __syncthreads(); long long t0=clock64(), g0=gt();
  #pragma unroll 4
  for(int it=0;it<IT;it++){
    #pragma unroll
    for(int i=0;i<CH;i++) asm volatile("fma.rn.f32 %0,%0,%1,%2;":"+f"(a[i]):"f"(b),"f"(c));
  }
  __syncthreads(); long long t1=clock64(), g1=gt();
  float s=0; for(int i=0;i<CH;i++) s+=a[i]; out[blockIdx.x*blockDim.x+threadIdx.x]=s;
  if(threadIdx.x==0){ clk[2*blockIdx.x]=t1-t0; clk[2*blockIdx.x+1]=g1-g0; }
}
extern "C" __global__ void k_ffma2(float* out, long long* clk){
  unsigned long long a[CH]; float f=threadIdx.x*1e-3f;
  for(int i=0;i<CH;i++) asm volatile("mov.b64 %0,{%1,%2};":"=l"(a[i]):"f"(f+i),"f"(f-i));
  unsigned long long b,c; asm volatile("mov.b64 %0,{%1,%1};":"=l"(b):"f"(1.0001f)); asm volatile("mov.b64 %0,{%1,%1};":"=l"(c):"f"(1e-7f));
  __syncthreads(); long long t0=clock64(), g0=gt();
  #pragma unroll 4
  for(int it=0;it<IT;it++){
    #pragma unroll
    for(int i=0;i<CH;i++) asm volatile("fma.rn.f32x2 %0,%0,%1,%2;":"+l"(a[i]):"l"(b),"l"(c));
  }
  __syncthreads(); long long t1=clock64(), g1=gt();
  float s=0; for(int i=0;i<CH;i++){float x,y; asm("mov.b64 {%0,%1},%2;":"=f"(x),"=f"(y):"l"(a[i])); s+=x+y;}
  out[blockIdx.x*blockDim.x+threadIdx.x]=s;
  if(threadIdx.x==0){ clk[2*blockIdx.x]=t1-t0; clk[2*blockIdx.x+1]=g1-g0; }
}
extern "C" __global__ void k_ex2(float* out, long long* clk){
  float a[CH]; for(int i=0;i<CH;i++) a[i]=threadIdx.x*1e-6f+i*1e-3f;
  __syncthreads(); long long t0=clock64(), g0=gt();
  #pragma unroll 4
  for(int it=0;it<IT;it++){
    #pragma unroll
    for(int i=0;i<CH;i++) asm volatile("ex2.approx.ftz.f32 %0,%0;":"+f"(a[i]));
  }
  __syncthreads(); long long t1=clock64(), g1=gt();
  float s=0; for(int i=0;i<CH;i++) s+=a[i]; out[blockIdx.x*blockDim.x+threadIdx.x]=s;
  if(threadIdx.x==0){ clk[2*blockIdx.x]=t1-t0; clk[2*blockIdx.x+1]=g1-g0; }
}
extern "C" __global__ void k_rcp(float* out, long long* clk){
  float a[CH]; for(int i=0;i<CH;i++) a[i]=1.f+threadIdx.x*1e-6f+i*1e-3f;
  __syncthreads(); long long t0=clock64(), g0=gt();
  #pragma unroll 4
  for(int it=0;it<IT;it++){
    #pragma unroll
    for(int i=0;i<CH;i++) asm volatile("rcp.approx.ftz.f32 %0,%0;\n\tadd.f32 %0,%0,0f3F800000;":"+f"(a[i]));
  }
  __syncthreads(); long long t1=clock64(), g1=gt();
  float s=0; for(int i=0;i<CH;i++) s+=a[i]; out[blockIdx.x*blockDim.x+threadIdx.x]=s;
  if(threadIdx.x==0){ clk[2*blockIdx.x]=t1-t0; clk[2*blockIdx.x+1]=g1-g0; }
}
'''
res = b200probe.resources(src); print(res)
s = b200probe.sass(src)
for op in ['FFMA2','FFMA ','MUFU.EX2','MUFU.RCP','FADD']:
    print(op, len(re.findall(re.escape(op), s)))
CH, IT = 8, 4096
for name,lanes in [('k_ffma',1),('k_ffma2',2),('k_ex2',1),('k_rcp',1)]:
    k = b200probe.cuda_kernel(src, name)
    blk=512; grid=148*4
    out=torch.empty(grid*blk,device='cuda'); clk=torch.zeros(2*grid,dtype=torch.int64,device='cuda')
    k((grid,),(blk,),out,clk); torch.cuda.synchronize()
    e0=torch.cuda.Event(enable_timing=True); e1=torch.cuda.Event(enable_timing=True)
    e0.record(); k((grid,),(blk,),out,clk); e1.record(); torch.cuda.synchronize()
    ms=e0.elapsed_time(e1)
    c=clk[0::2].double().median().item(); ns=clk[1::2].double().median().item()
    mhz=c/ns*1e3
    ops=grid*blk*IT*CH*lanes
    print(name,'clk/ns -> %.0f MHz'%mhz,'per-clk rate (clock64, 2048 thr) %.1f'%(2048*IT*CH*lanes/c),
          'wall-based lanes/clk/SM %.1f'%(ops/(ms*1e-3)/148/(mhz*1e6)), 'kernel %.3f ms'%ms)

import b200probe, torch
src = r'''
extern "C" __global__ void k_write(float4* p, long long n4, int pol){
  unsigned long long pl; 
  if(pol==1) asm volatile("createpolicy.fractional.L2::evict_last.b64 %0, 1.0;":"=l"(pl));
  else if(pol==2) asm volatile("createpolicy.fractional.L2::evict_first.b64 %0, 1.0;":"=l"(pl));
  else asm volatile("createpolicy.fractional.L2::evict_normal.b64 %0, 1.0;":"=l"(pl));
  for(long long i=blockIdx.x*(long long)blockDim.x+threadIdx.x;i<n4;i+=(long long)gridDim.x*blockDim.x){
    float4 v=make_float4(i,1,2,3);
    asm volatile("st.global.L2::cache_hint.v4.f32 [%0],{%1,%2,%3,%4},%5;"::"l"(p+i),"f"(v.x),"f"(v.y),"f"(v.z),"f"(v.w),"l"(pl):"memory");
  }
}
extern "C" __global__ void k_read(const float4* p, long long n4, float* out){
  float s=0;
  long long stride=(long long)gridDim.x*blockDim.x;
  long long i=blockIdx.x*(long long)blockDim.x+threadIdx.x;
  for(;i+3*stride<n4;i+=4*stride){
    float4 a=p[i],b=p[i+stride],c=p[i+2*stride],d=p[i+3*stride];
    s+=a.x+a.y+a.z+a.w+b.x+b.y+b.z+b.w+c.x+c.y+c.z+c.w+d.x+d.y+d.z+d.w;
  }
  for(;i<n4;i+=stride){float4 a=p[i]; s+=a.x+a.y+a.z+a.w;}
  if(s==1234.5f) out[0]=s;
}
'''
kw=b200probe.cuda_kernel(src,'k_write'); kr=b200probe.cuda_kernel(src,'k_read')
L2=126*2**20
flush=torch.empty(2*L2//4,device='cuda')
ws=torch.empty(200*2**20//4,device='cuda'); out=torch.zeros(1,device='cuda')
ws2=torch.empty(200*2**20//4,device='cuda')
def ev(): return torch.cuda.Event(enable_timing=True)
def tread(t,n4):
    e0,e1=ev(),ev(); e0.record(); kr((148*8,),(512,),t,b200probe.i64(n4),out); e1.record(); torch.cuda.synchronize(); return e0.elapsed_time(e1)*1e3
for MB in [13,38,76,100]:
    n4=MB*2**20//16
    r={}
    for pol,name in [(1,'EL'),(0,'EN'),(2,'EF')]:
        ts=[]
        for rep in range(3):
            flush.zero_(); kw((148*4,),(512,),ws,b200probe.i64(n4),pol); ts.append(tread(ws,n4))
        r[name]=min(ts)
    ts=[]
    for rep in range(3):
        flush.zero_(); ts.append(tread(ws2,n4))  # cold DRAM read after flush
    r['cold']=min(ts)
    ts=[]
    for rep in range(3):
        flush.zero_(); tread(ws2,n4); ts.append(tread(ws2,n4))  # warm clean re-read
    r['warm_clean']=min(ts)
    print(MB,'MB', {k:'%.1f us (%.1f TB/s)'%(v,MB*2**20/v/1e6) for k,v in r.items()})
# empty launch overhead
e0,e1=ev(),ev(); e0.record(); kr((148*8,),(512,),ws,b200probe.i64(0),out); e1.record(); torch.cuda.synchronize(); print('empty read kernel %.1f us'%(e0.elapsed_time(e1)*1e3))

