import b200probe, torch
src = r'''
#define TF 16384
extern "C" __global__ void k_store(float* out, int ways){
  int tile=blockIdx.x/ways; float* o=out+(long long)tile*TF;
  for(int i=threadIdx.x*4;i<TF;i+=blockDim.x*4) *(float4*)(o+i)=make_float4(1,2,3,i);
}
extern "C" __global__ void k_red1(float* out, int ways){
  int tile=blockIdx.x/ways; float* o=out+(long long)tile*TF;
  for(int i=threadIdx.x;i<TF;i+=blockDim.x) atomicAdd(o+i,1.0f);
}
extern "C" __global__ void k_red4(float* out, int ways){
  int tile=blockIdx.x/ways; float* o=out+(long long)tile*TF;
  for(int i=threadIdx.x*4;i<TF;i+=blockDim.x*4)
    asm volatile("red.global.add.v4.f32 [%0],{%1,%2,%3,%4};"::"l"(o+i),"f"(1.f),"f"(2.f),"f"(3.f),"f"(4.f):"memory");
}
extern "C" __global__ void k_bulk(float* out, int ways){
  extern __shared__ __align__(128) float sm[];
  int tile=blockIdx.x/ways; float* o=out+(long long)tile*TF;
  for(int i=threadIdx.x*4;i<TF;i+=blockDim.x*4) *(float4*)(sm+i)=make_float4(1,2,3,4);
  asm volatile("fence.proxy.async.shared::cta;":::"memory");
  __syncthreads();
  if(threadIdx.x==0){
    unsigned s=(unsigned)__cvta_generic_to_shared(sm);
    asm volatile("cp.reduce.async.bulk.global.shared::cta.bulk_group.add.f32 [%0],[%1],%2;"::"l"(o),"r"(s),"r"(TF*4):"memory");
    asm volatile("cp.async.bulk.commit_group;":::"memory");
    asm volatile("cp.async.bulk.wait_group 0;":::"memory");
  }
  __syncthreads();
}
'''
ks={n:b200probe.cuda_kernel(src,n) for n in ['k_store','k_red1','k_red4','k_bulk']}
ks['k_bulk'].set_smem(65536)
for tiles in [25,100]:
    ways=4
    out=torch.zeros(tiles*16384,device='cuda')
    res={}
    for n,k in ks.items():
        sm=65536 if n=='k_bulk' else 0
        f=lambda o,k=k,sm=sm: k((tiles*ways,),(512,),o,ways,smem=sm)
